"""The install scripts the dashboard hands to endpoints. Plain text, generated per request so the
one-liner carries the controller address and join token and nothing has to be typed on the host."""
from __future__ import annotations

SH = r'''#!/bin/sh
# ChaosLab endpoint agent installer. Generated by the Chaos Monkey dashboard at __CONTROLLER__
set -eu
CONTROLLER='__CONTROLLER__'
TOKEN='__TOKEN__'
NAME="${CHAOS_AGENT_NAME:-}"
BIN=/usr/local/bin/chaos-agent
say()  { printf '%s\n' "$*"; }
fail() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

[ "$(id -u)" = 0 ] || fail "run this as root, for example:  curl -fsSL '$CONTROLLER/install.sh?token=$TOKEN' | sudo sh"
[ "$(uname -s)" = Linux ] || fail "this installer is for Linux. On Windows use the PowerShell command from the dashboard."
case "$(uname -m)" in
  x86_64|amd64) ARCH=amd64 ;;
  aarch64|arm64) ARCH=arm64 ;;
  *) fail "no agent build for CPU type $(uname -m) (amd64 and arm64 are available)" ;;
esac
fetch() {
  if command -v curl >/dev/null 2>&1; then curl -fsSL "$1" -o "$2"
  elif command -v wget >/dev/null 2>&1; then wget -q "$1" -O "$2"
  else fail "neither curl nor wget is installed"; fi
}

say "[1/3] Downloading the agent (linux/$ARCH) from $CONTROLLER"
fetch "$CONTROLLER/dl/chaos-agent-linux-$ARCH" "$BIN.new" || fail "download failed. Is $CONTROLLER reachable from this host?"
chmod 0755 "$BIN.new"
mv -f "$BIN.new" "$BIN"

say "[2/3] Checking that the controller accepts this endpoint"
"$BIN" check --controller "$CONTROLLER" --token "$TOKEN" || fail "the controller did not accept the join token. Copy the command from the dashboard again."

say "[3/3] Starting the agent"
set -- run --controller "$CONTROLLER" --token "$TOKEN"
[ -z "$NAME" ] || set -- "$@" --name "$NAME"
if [ -d /run/systemd/system ] && command -v systemctl >/dev/null 2>&1; then
  cat > /etc/systemd/system/chaos-agent.service <<UNIT
[Unit]
Description=ChaosLab endpoint agent
After=network-online.target
Wants=network-online.target

[Service]
ExecStart=$BIN $*
Restart=always
RestartSec=2
# Needs no privileges: unprivileged ports, a private state directory, nothing else writable.
DynamicUser=yes
StateDirectory=chaoslab
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes

[Install]
WantedBy=multi-user.target
UNIT
  systemctl daemon-reload
  systemctl enable chaos-agent >/dev/null 2>&1 || true
  systemctl restart chaos-agent
  HOW="systemd service chaos-agent (starts at boot; logs: journalctl -u chaos-agent)"
else
  # No systemd (containers, Alpine): run in the background now.
  if [ -f /var/run/chaos-agent.pid ]; then kill "$(cat /var/run/chaos-agent.pid)" 2>/dev/null || true; fi
  nohup "$BIN" "$@" --log /var/log/chaos-agent.log >/dev/null 2>&1 &
  echo $! > /var/run/chaos-agent.pid
  HOW="background process (no systemd here, so it will NOT survive a reboot; log: /var/log/chaos-agent.log)"
fi

# Host firewalls: open the default test port. Flows on other ports need their own rule.
if command -v ufw >/dev/null 2>&1 && ufw status 2>/dev/null | grep -q '^Status: active'; then
  ufw allow 30200 >/dev/null 2>&1 && say "      ufw: allowed port 30200 (default test port)"
elif command -v firewall-cmd >/dev/null 2>&1 && firewall-cmd --state >/dev/null 2>&1; then
  firewall-cmd -q --permanent --add-port=30200/udp --add-port=30200/tcp && firewall-cmd -q --reload \
    && say "      firewalld: allowed port 30200 (default test port)"
fi

say ""
say "Done. Running as: $HOW"
say "This endpoint appears on the dashboard within a few seconds: $CONTROLLER/#endpoints"
say "To remove it:  curl -fsSL $CONTROLLER/uninstall.sh | sudo sh"
'''

UNINSTALL_SH = r'''#!/bin/sh
# ChaosLab endpoint agent uninstaller.
set -u
[ "$(id -u)" = 0 ] || { echo "ERROR: run this as root" >&2; exit 1; }
if command -v systemctl >/dev/null 2>&1 && [ -f /etc/systemd/system/chaos-agent.service ]; then
  systemctl disable --now chaos-agent >/dev/null 2>&1
  rm -f /etc/systemd/system/chaos-agent.service
  systemctl daemon-reload
fi
if [ -f /var/run/chaos-agent.pid ]; then kill "$(cat /var/run/chaos-agent.pid)" 2>/dev/null; rm -f /var/run/chaos-agent.pid; fi
rm -rf /usr/local/bin/chaos-agent /var/lib/chaoslab /var/lib/private/chaoslab
echo "chaos-agent removed. Remove the endpoint from the dashboard as well if it will not come back."
'''

PS1 = r'''# ChaosLab endpoint agent installer. Generated by the Chaos Monkey dashboard at __CONTROLLER__
$ErrorActionPreference = 'Stop'
$Controller = '__CONTROLLER__'
$Token = '__TOKEN__'
$Task = 'ChaosLab Agent'

$me = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
if (-not $me.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Host 'ERROR: open PowerShell with "Run as administrator" and paste the command again.' -ForegroundColor Red
    return
}
$Dir = Join-Path $env:ProgramData 'ChaosLab'
$Exe = Join-Path $Dir 'chaos-agent.exe'
New-Item -ItemType Directory -Force -Path $Dir | Out-Null

Write-Host "[1/4] Downloading the agent from $Controller"
Stop-ScheduledTask -TaskName $Task -ErrorAction SilentlyContinue
Get-Process -Name 'chaos-agent' -ErrorAction SilentlyContinue | Stop-Process -Force
$ProgressPreference = 'SilentlyContinue'
try { Invoke-WebRequest -UseBasicParsing -Uri "$Controller/dl/chaos-agent-windows-amd64.exe" -OutFile $Exe }
catch { Write-Host "ERROR: download failed. Is $Controller reachable from this host? $_" -ForegroundColor Red; return }

Write-Host '[2/4] Checking that the controller accepts this endpoint'
& $Exe check --controller $Controller --token $Token
if ($LASTEXITCODE -ne 0) { Write-Host 'ERROR: copy the command from the dashboard again.' -ForegroundColor Red; return }

Write-Host '[3/4] Allowing test traffic through Windows Firewall (inbound, this program only)'
Remove-NetFirewallRule -DisplayName $Task -ErrorAction SilentlyContinue
New-NetFirewallRule -DisplayName $Task -Direction Inbound -Program $Exe -Action Allow -Profile Any | Out-Null

Write-Host '[4/4] Starting the agent (scheduled task, starts at boot)'
$arguments = "run --controller $Controller --token $Token --state `"$Dir\agent.json`" --log `"$Dir\agent.log`""
if ($env:CHAOS_AGENT_NAME) { $arguments += " --name `"$($env:CHAOS_AGENT_NAME)`"" }
$action = New-ScheduledTaskAction -Execute $Exe -Argument $arguments
$trigger = New-ScheduledTaskTrigger -AtStartup
# Defaults would stop the task after three days and refuse to start it on battery.
$settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries `
    -ExecutionTimeLimit ([TimeSpan]::Zero) -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -StartWhenAvailable
try {
    # Least privilege first: the agent needs nothing beyond its own folder.
    & icacls $Dir /grant '*S-1-5-19:(OI)(CI)M' | Out-Null
    $principal = New-ScheduledTaskPrincipal -UserId 'LOCALSERVICE' -LogonType ServiceAccount
    Register-ScheduledTask -TaskName $Task -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force | Out-Null
} catch {
    $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    Register-ScheduledTask -TaskName $Task -Action $action -Trigger $trigger -Settings $settings -Principal $principal -Force | Out-Null
}
Start-ScheduledTask -TaskName $Task

Write-Host ''
Write-Host "Done. Running as scheduled task '$Task' (log: $Dir\agent.log)."
Write-Host "This endpoint appears on the dashboard within a few seconds: $Controller/#endpoints"
Write-Host "To remove it:  irm $Controller/uninstall.ps1 | iex"
'''

UNINSTALL_PS1 = r'''# ChaosLab endpoint agent uninstaller.
$Task = 'ChaosLab Agent'
Stop-ScheduledTask -TaskName $Task -ErrorAction SilentlyContinue
Unregister-ScheduledTask -TaskName $Task -Confirm:$false -ErrorAction SilentlyContinue
Get-Process -Name 'chaos-agent' -ErrorAction SilentlyContinue | Stop-Process -Force
Remove-NetFirewallRule -DisplayName $Task -ErrorAction SilentlyContinue
Remove-Item -Recurse -Force (Join-Path $env:ProgramData 'ChaosLab') -ErrorAction SilentlyContinue
Write-Host 'chaos-agent removed. Remove the endpoint from the dashboard as well if it will not come back.'
'''

BAD_TOKEN_SH = '''#!/bin/sh
echo "ERROR: the Chaos Monkey dashboard does not recognise that join token." >&2
echo "Open the dashboard, go to Endpoints, and copy the install command again." >&2
exit 1
'''
BAD_TOKEN_PS1 = '''Write-Host 'ERROR: the Chaos Monkey dashboard does not recognise that join token.' -ForegroundColor Red
Write-Host 'Open the dashboard, go to Endpoints, and copy the install command again.'
'''


def render(template: str, controller: str, token: str) -> str:
    return template.replace("__CONTROLLER__", controller).replace("__TOKEN__", token)
